mapper.select:
SELECT command_id, action, business_effect_key, execution_attempt_id, attempt_no, payload_digest, digest_version, state, safe_close_id, previous_command_id
FROM stock_command
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND source_service=#{sourceService}
AND command_id=#{commandId} FOR UPDATE

SELECT command_id, action, business_effect_key, execution_attempt_id, attempt_no, payload_digest, digest_version, state, safe_close_id, previous_command_id
FROM stock_command
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND source_service=#{sourceService}
AND command_id=#{commandId}

SELECT command_id, action, business_effect_key, execution_attempt_id, attempt_no, payload_digest, digest_version, state
FROM stock_command
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND source_service=#{sourceService}
AND business_effect_key=#{effectId}
AND action=#{action}
ORDER BY attempt_no DESC
LIMIT 1

mapper.update:
UPDATE stock_command
SET safe_close_id=#{closeId}, safe_close_version=safe_close_version+1, safe_close_evidence=CAST(#{evidence} AS JSON), updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND source_service=#{sourceService}
AND command_id=#{commandId}

UPDATE stock_command
SET state=#{toState}, result_json=CAST(#{resultJson} AS JSON), version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND source_service=#{sourceService}
AND command_id=#{commandId}
AND state=#{fromState}

mapper.select:
