FROM execution_permit
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND source_service=#{sourceService}
AND command_id=#{commandId} FOR UPDATE

mapper.update:
UPDATE execution_permit
SET state=#{toState}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND source_service=#{sourceService}
AND command_id=#{commandId}
AND state=#{fromState}

mapper.select:
SELECT id, quantity, reversed_qty, command_id
FROM stock_posting
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{id} FOR UPDATE

mapper.update:
UPDATE stock_posting
SET reversed_qty=reversed_qty+#{qty}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{id}
AND reversed_qty+#{qty}<=quantity

mapper.select:
SELECT id, quantity, source_execution_id, source_document_id, action, created_at
FROM stock_posting WHERE enterprise_id=#{enterpriseId} AND warehouse_id=#{warehouseId}
  AND source_service=#{sourceService} AND command_id=#{commandId}
